QByteArray hardwareProbeClip() {
    return QByteArray::fromRawData(reinterpret_cast<const char *>(kClip), static_cast<int>(sizeof(kClip)));
}

QString writeHardwareProbeClip(const QString &directory) {
    if (directory.isEmpty() || !isAllowedSpoolLocation(QDir(directory).absolutePath().toStdString())) return QString();
    const QByteArray clip = hardwareProbeClip();
    const QString path = QDir(directory).absoluteFilePath(QStringLiteral("hardware-probe-h264.mp4"));
    QFile existing(path);
    if (existing.open(QIODevice::ReadOnly) && existing.size() == clip.size() && existing.readAll() == clip) return path;
    existing.close();
    if (!QDir().mkpath(directory)) return QString();
    QFile out(path);
    if (!out.open(QIODevice::WriteOnly | QIODevice::Truncate) || out.write(clip) != clip.size()) return QString();
    return path;
}

